// Serve the Shelcy logo as a crawlable PNG favicon.
const icon = Buffer.from('', 'base64');
module.exports = (request, response) => {
  response.setHeader('Content-Type', 'image/png');
  response.setHeader('Cache-Control', 'public, max-age=86400, s-maxage=604800');
  response.setHeader('Content-Length', String(icon.length));
  response.statusCode = 200;
  response.end(request.method === 'HEAD' ? undefined : icon);
};
